class Solution { public int[] findOriginalArray(int[] changed){if(changed.length%2==1)return new int[0];Arrays.sort(changed);Map<Integer,Integer> frequency=new HashMap<>();for(int value:changed)frequency.merge(value,1,Integer::sum);int[] answer=new int[changed.length/2];int index=0;for(int value:changed)if(frequency.get(value)>0){if(frequency.getOrDefault(value*2,0)==0)return new int[0];frequency.put(value,frequency.get(value)-1);frequency.put(value*2,frequency.get(value*2)-1);answer[index++]=value;}return answer;} }
